'use strict';
const $=id=>document.getElementById(id);
const state={dictionaries:new Map(),results:[],visible:30,lastInputs:[]};
function escapeHtml(s){return String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function loadWords(ids){const merged=new Set();for(const id of ids){if(!state.dictionaries.has(id))state.dictionaries.set(id,new Set(String(EMBEDDED_DICT_TEXT[id]||'').split(/\r?\n/).map(TanukiCore.normalize).filter(Boolean)));for(const word of state.dictionaries.get(id))merged.add(word)}return merged}
function renumber(){const rows=[...document.querySelectorAll('.input-card')];rows.forEach((row,i)=>{row.querySelector('.token-label').textContent=`消す対象${i+1}`;row.querySelector('.remove-input').hidden=rows.length<=2});$('addInput').disabled=rows.length>=4}
function addInput(value='',min=1,max=3){if(document.querySelectorAll('.input-card').length>=4)return;const row=$('inputTemplate').content.firstElementChild.cloneNode(true);row.querySelector('.token-input').value=value;row.querySelector('.count-min').value=min;row.querySelector('.count-max').value=max;row.querySelector('.remove-input').addEventListener('click',()=>{row.remove();renumber()});$('inputList').append(row);renumber()}
function readInputs(){return[...document.querySelectorAll('.input-card')].map(row=>({token:row.querySelector('.token-input').value,min:row.querySelector('.count-min').value,max:row.querySelector('.count-max').value}))}
function highlight(word,token,mode){if(mode==='sequence')return escapeHtml(word).split(escapeHtml(token)).join(`<mark>${escapeHtml(token)}</mark>`);const set=new Set(Array.from(TanukiCore.normalizeIndividual(token)));return Array.from(TanukiCore.normalizeIndividual(word)).map(c=>set.has(c)?`<mark>${escapeHtml(c)}</mark>`:escapeHtml(c)).join('')}
function render(){const mode=document.querySelector('input[name="mode"]:checked').value;const direction=$('sortOrder').value;const sorted=[...state.results].sort((a,b)=>(direction==='long'?b.length-a.length:a.length-b.length)||a.candidate.localeCompare(b.candidate,'ja'));const shown=sorted.slice(0,state.visible);$('moreButton').hidden=shown.length>=sorted.length;if(!shown.length){$('results').innerHTML='<div class="empty">この条件では候補が見つかりませんでした。</div>';return}$('results').innerHTML=shown.map((r,i)=>`<article class="result-card" style="--i:${i}"><div class="candidate-line"><span class="number">${String(i+1).padStart(2,'0')}</span><h3>${escapeHtml(r.candidate)}</h3><span class="length">${r.length}文字</span></div><div class="proof-grid">${state.lastInputs.map((input,j)=>`<div><span class="proof-label tone-${j+1}">対象${j+1}を消す</span><p>${highlight(r.candidate,input.token,mode)}<i>→</i><strong>${escapeHtml(r.outputs[j])}</strong></p></div>`).join('')}</div></article>`).join('')}
function runSearch(){$('error').textContent='';$('searchButton').disabled=true;$('searchButton').textContent='検索中…';setTimeout(()=>{try{const ids=[...document.querySelectorAll('input[name="dictionary"]:checked')].map(x=>x.value);if(!ids.length)throw new Error('辞書を1つ以上選んでください。');state.lastInputs=readInputs();const started=performance.now();const output=TanukiCore.search({inputs:state.lastInputs,lengthMin:$('lengthMin').value,lengthMax:$('lengthMax').value,omitRepeats:$('omitRepeats').checked,mode:document.querySelector('input[name="mode"]:checked').value,words:loadWords(ids)});state.results=output.results;state.visible=30;render();$('summary').textContent=`${output.results.length.toLocaleString()}件 / ${Math.round(performance.now()-started).toLocaleString()}ms${output.truncated?' / 探索上限まで':''}`}catch(e){$('error').textContent=e.message;$('summary').textContent='入力を確認してください'}finally{$('searchButton').disabled=false;$('searchButton').textContent='検索'}},30)}
addInput('',2,3);addInput('',2,3);
$('addInput').addEventListener('click',()=>addInput('',1,3));$('searchButton').addEventListener('click',runSearch);$('sortOrder').addEventListener('change',()=>{state.visible=30;render()});$('moreButton').addEventListener('click',()=>{state.visible+=30;render()});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input'))runSearch()});
